const pages=[['dashboard','Dashboard','▦'],['events','Business Events','◷'],['signals','Signals','≋'],['analysis','Risks & Opportunities','◇'],['impact','Financial Impact','↗'],['recommendations','Recommendations','☷'],['decisions','Decision Center','✓']];
const totals={principal:sum('principal'),revenue:sum('revenue'),ar:sum('ar'),overdue:sum('overdue')};
const weighted=key=>customers.reduce((s,c)=>s+c.principal*c[key],0)/totals.principal;
const money=n=>'$'+n.toFixed(1)+'M';
const pct=n=>n.toFixed(1)+'%';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function sum(key,rows=customers){return rows.reduce((s,c)=>s+c[key],0)}
function route(){const parts=location.hash.slice(1).split('/');return {page:pages.some(p=>p[0]===parts[0])?parts[0]:'dashboard',id:parts[1]||'telecom'}}
function badge(level){return `<span class="pill ${level}">${level}</span>`}
function head(title,sub,extra=''){return `<div class="page-head"><div><div class="eyebrow">Leasing financial intelligence</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${extra||'<span class="period">Global portfolio · USD</span>'}</div>`}
function kpi(label,value,sub,cls=''){return `<div class="kpi"><div class="kpi-label">${label}</div><div class="kpi-value ${cls}">${value}</div><small>${sub}</small></div>`}
function panel(title,body,sub='',link=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link}</div>${body}</section>`}
function chart(series,labels,unit='%',second=null){const all=second?series.concat(second):series;const max=Math.max(...all)*1.18,min=Math.max(0,Math.min(...all)*.7),w=600,h=195;const x=i=>48+i*520/(series.length-1),y=n=>162-(n-min)/(max-min)*136;const pts=arr=>arr.map((n,i)=>`${x(i)},${y(n)}`).join(' ');return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(labels.map((l,i)=>l+': '+series[i]+unit+(second?', comparison '+second[i]+unit:'')).join('; '))}">${[0,1,2,3].map(i=>{let yy=26+i*45;return `<line x1="48" y1="${yy}" x2="570" y2="${yy}" stroke="#edf1f6"/><text x="0" y="${yy+4}">${(max-i*(max-min)/3).toFixed(1)}${unit}</text>`}).join('')}<polygon points="48,162 ${pts(series)} 568,162" fill="#edf4ff"/>${second?`<polyline points="${pts(second)}" fill="none" stroke="#9badc4" stroke-dasharray="5 5" stroke-width="2"/>`:''}<polyline points="${pts(series)}" fill="none" stroke="#3678df" stroke-width="2.7"/>${series.map((n,i)=>`<circle cx="${x(i)}" cy="${y(n)}" r="3.5" fill="white" stroke="#3678df" stroke-width="2"/><text x="${x(i)}" y="187" text-anchor="middle">${labels[i]}</text>`).join('')}</svg>`}
