const FLOW=[['events','Business Events','What happened?'],['signals','Intelligence Signals','What does it tell us?'],['analysis','Risks & Opportunities','What could happen?'],['impact','Financial Impact','How much is at stake?'],['recommendations','Recommendations','What should we do?'],['decisions','Business Decisions','What do we decide?']];
const MODEL_KEY='leaseaegis-operating-model-v2';
const ui={event:'payment',eventFilter:'All events',search:'',decisionFilter:'All statuses',advisor:'attention'};
function currentCase(){const id=location.hash.slice(1).split('/')[1];return CASES.find(c=>c.id===id)||CASES.find(c=>c.id===ui.event)||CASES[0]}
function account(c){return customers.find(a=>a.id===c.customer)}
function go(stage,c=currentCase()){return '#'+stage+'/'+c.id}
function dollars(n){return Math.abs(n)<1?'$'+Math.round(n*1000).toLocaleString('en-US')+'K':money(n)}
function dateLabel(d){return new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'})}
function loadModel(){try{const s=JSON.parse(localStorage.getItem(MODEL_KEY)||'{}');return s&&typeof s==='object'&&!Array.isArray(s)?s:{}}catch{return {}}}
function decision(c){const d=loadModel()[c.id];return d&&Array.isArray(d.history)?d:{status:'Recommended',option:0,owner:c.owner,targetDate:c.targetDate,history:[]}}
function persist(c,d){const all=loadModel();all[c.id]=d;try{localStorage.setItem(MODEL_KEY,JSON.stringify(all));return true}catch{toast('Unable to save. Your inputs remain available; browser storage may be blocked.');return false}}
function statusBadge(s){return `<span class="pill status-${s.replaceAll(' ','-')}">${s}</span>`}
function process(stage,c){return `<nav class="process-flow" aria-label="Event to decision workflow">${FLOW.map(([key,label,q],i)=>`<a href="${go(key,c)}" class="${key===stage?'current':''}" ${key===stage?'aria-current="step"':''}><span class="step-number">${i+1}</span><span>${label}<small>${q}</small></span></a>`).join('')}</nav>`}
function context(c){return `<section class="context-strip" aria-label="Selected event"><div><span class="eyebrow">${c.type} · ${c.id.toUpperCase()}</span><strong>${c.title}</strong><small>${account(c).name}</small></div><div>${badge(c.severity)}<small>Review ${dateLabel(c.next)}</small></div><label>Event context<select id="event-context">${CASES.map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${x.type}</option>`).join('')}</select></label></section>`}
function stepHead(title,subtitle,stage,c){return head(title,subtitle,'<span class="period">22 Oct 2026 · Illustrative portfolio</span>')+process(stage,c)+context(c)}
function nextStep(stage,label,c){return `<div class="next-step"><span>Continue with the same event and customer</span><a class="button primary" href="${go(stage,c)}">${label} →</a></div>`}
function eventCard(c){return `<article class="event-card"><div class="action-meta"><span class="eyebrow">${c.type}</span>${badge(c.severity)}</div><h2><a href="${go('events',c)}">${c.title}</a></h2><p>${c.description}</p><div class="event-impact"><strong>${dollars(c.amount)}</strong><span>${c.amountLabel}</span></div><p class="business-consequence">${c.impact}</p><div class="event-dates"><span>Detected<strong>${dateLabel(c.detected)}</strong></span><span>Next review<strong>${dateLabel(c.next)}</strong></span></div><div class="event-card-foot"><span>${account(c).name}</span><a href="${go('signals',c)}">Review signals →</a></div></article>`}
function overview(){const all=CASES.map(c=>({c,d:decision(c)}));const measured=all.filter(x=>x.d.observed!==undefined);const cash=measured.filter(x=>x.c.metric==='Cash collected').reduce((s,x)=>s+x.d.observed,0);return head('Executive Overview','What requires your attention today? Start with the event. Follow it through to a decision.',`<a class="button primary" href="#events/payment">Review business events →</a>`)+`<div class="kpis">${kpi('Total portfolio value',money(totals.principal),'Financed principal')}${kpi('Portfolio yield',pct(weighted('yield')),'Annualized finance income / principal')}${kpi('Outstanding receivables',money(totals.ar),'Open customer invoices')}${kpi('Collection exposure',money(totals.overdue),'Overdue AR · not an estimated loss','negative')}${kpi('Upcoming renewals','3','$10.8M annual value · next 30 days')}</div><section class="journey-banner"><div><div class="eyebrow">FROM INFORMATION TO ACTION</div><h2>One event. A connected decision journey.</h2><p>Follow Global Telecom’s $4.5M overdue balance from detection to Finance approval and measured results.</p></div><a class="button" href="#events/payment">Start the walkthrough →</a></section>${process('',CASES[0])}<div class="grid equal">${panel('Top risks',CASES.filter(c=>['payment','renewal','modification'].includes(c.id)).sort((a,b)=>a.rank-b.rank).map(c=>`<div class="risk-item"><span class="rank">${c.rank}</span><div class="body"><h3><a href="${go('analysis',c)}">${c.category}</a></h3><p>${account(c).name}</p><p>${c.impact}</p></div><div class="risk-amount">${dollars(c.amount)}<small>${c.amountLabel}</small></div></div>`).join(''),'Different impact measures; do not sum across events','<a href="#analysis/payment">Review risks →</a>')}${panel('Top opportunity',`<div class="opportunity-highlight"><span class="pill Low">Growth opportunity</span><h3>Cloud capacity expansion</h3><strong>$4.0M</strong><p>Uncontracted demand. A conditional Q4 start could add $600K revenue.</p><a href="#impact/expansion">Assess financial impact →</a></div><div class="insight"><strong>Validate first.</strong> Confirm budget and timing before committing delivery capacity or changing the base forecast.</div>`,'Cloud Infrastructure Provider')}</div>`+panel('Recommended actions',`<div class="action-list">${[CASES[0],CASES[2],CASES[5]].map(c=>`<article class="action-card"><div class="action-meta">${badge(c.severity)}${statusBadge(decision(c).status)}</div><h3>${c.rec}</h3><p>${c.reason}</p><a href="${go('recommendations',c)}">Compare actions →</a></article>`).join('')}</div>`,'Every action links back to an event, its evidence and financial consequence')+panel('Business value summary',`<div class="value-summary"><div><strong>${all.filter(x=>x.d.history.length).length}</strong><span>Events with a Finance decision</span></div><div><strong>${measured.length}</strong><span>Outcomes measured</span></div><div><strong>${cash?dollars(cash):'Not measured'}</strong><span>Simulated cash collected</span></div><div><strong>${all.filter(x=>x.d.status==='Outcome Achieved').length}</strong><span>Outcome targets achieved</span></div></div><p class="note">Results appear only after you record an outcome. Revenue, profit and exposure changes are not added to cash collections. All decisions and results are local simulations.</p>`)}
function businessEvents(){const c=currentCase();const rows=CASES.filter(x=>(ui.eventFilter==='All events'||x.severity===ui.eventFilter)&&`${x.type} ${x.title} ${account(x).name}`.toLowerCase().includes(ui.search.toLowerCase()));return stepHead('Business Events','Monitor meaningful changes across the leasing portfolio.','events',c)+`<div class="panel selected-event"><div><span class="eyebrow">SELECTED EVENT</span><h2>${c.title}</h2><p>${c.description}</p><p><strong>Why Finance should care:</strong> ${c.impact}</p></div><a class="button primary" href="${go('signals',c)}">Examine intelligence signals →</a></div><div class="filter-row"><input id="event-search" type="search" aria-label="Search business events" placeholder="Search events or customers" value="${esc(ui.search)}"><label for="event-severity">Severity</label><select id="event-severity">${['All events','High','Medium'].map(v=>`<option ${ui.eventFilter===v?'selected':''}>${v}</option>`).join('')}</select><span class="count">${rows.length} events · ${new Set(rows.map(x=>x.customer)).size} affected customers</span></div><div class="event-grid">${rows.map(eventCard).join('')||'<p class="empty">No matching events. Change the search or severity.</p>'}</div><p class="note">Payment Delay and Customer Credit Change share Global Telecom’s $4.5M open AR. These are related events, not two separate exposures.</p>`}
function signals(){const c=currentCase();return stepHead('Intelligence Signals','See the information behind the concern or opportunity.','signals',c)+`<div class="grid equal">${panel('Internal Intelligence',`<div class="signal-list">${['Contracts','Payments','Accounting Records','Collections','Portfolio Metrics'].map((label,i)=>`<div class="signal-row"><span class="signal-index">0${i+1}</span><div><h3>${label}</h3><p>${c.internal[i]}</p><small>Portfolio snapshot · 22 Oct 2026 · illustrative Nexbill record</small></div></div>`).join('')}</div>`,'Operational evidence linked to the selected customer')}${panel('External Intelligence',`<div class="signal-list">${['Credit Indicators','Industry Trends','Public Sentiment','Economic Signals','Customer Business Events'].map((label,i)=>`<div class="signal-row external"><span class="signal-index">◇</span><div><h3>${label}</h3><p>${c.external[i]}</p><small>${/No |uncertain|unchanged|require/.test(c.external[i])?'Not validated / no adjustment applied':'Illustrative context · provider validation required'}</small></div></div>`).join('')}</div>`,'Context only · future feed coverage is not yet connected')}</div><div class="grid equal">${panel('Evidence strength',`<div class="score">${c.strength}<small> / 100</small></div><div class="progress-track"><i style="width:${c.strength}%"></i></div><p>${c.confidence} evidence confidence. ${c.driver}</p><p class="note">Illustrative evidence completeness assessment, not the probability of a financial outcome. External context does not modify risk levels before calibration.</p>`)}${panel('Direction of change',chart(c.history,['Jun','Jul','Aug','Sep','Oct'],' pts'),c.historyLabel+' · demonstration history')}</div>`+nextStep('analysis','Assess risks and opportunities',c)}
function analysis(){const c=currentCase();const isGrowth=c.category==='Growth Opportunity';return stepHead('Risk & Opportunity Analysis','Turn the detected evidence into a business assessment.','analysis',c)+`<div class="analysis-hero"><div><span class="eyebrow">${isGrowth?'OPPORTUNITY IDENTIFIED':'RISK IDENTIFIED'}</span><h2>${c.category}</h2><p>${c.summary}</p><div class="legend">${badge(c.severity)}<span>${c.trend}</span><span>${c.confidence} confidence</span></div></div><div class="analysis-score"><strong>${c.score}</strong><span>/ 100<br>${isGrowth?'Opportunity':'Risk'} score</span></div></div><div class="grid equal">${panel('Why this assessment matters',`<h3>Primary driver</h3><p>${c.driver}</p><div class="insight"><strong>Business summary</strong><br>${c.summary}</div><button data-analysis-detail="${c.id}" style="margin-top:16px">Open detailed analysis ↗</button><p class="note">Scores and confidence are illustrative assessments, not calibrated probabilities. Higher risk scores mean greater concern; higher opportunity scores mean greater potential.</p>`)}${panel('Risk & opportunity map',`<div class="heatmap">${CASES.map(x=>`<a href="${go('analysis',x)}" class="heat-cell ${x.id===c.id?'selected':''} ${x.category==='Growth Opportunity'?'growth':x.score>=80?'hot':'warm'}"><span>${x.category}</span><strong>${x.score}<small> / 100</small></strong><span>${x.trend} · ${x.confidence} confidence</span></a>`).join('')}</div>`,'Select an assessment to retain its event context')}</div>`+panel('Evidence → assessment → consequence',`<div class="evidence-chain"><div><span>Evidence</span><strong>${c.internal[1]}</strong></div><div><span>Assessment</span><strong>${c.category} · ${c.severity}</strong></div><div><span>Financial consequence</span><strong>${c.impact}</strong></div></div>`)+nextStep('impact','Quantify financial impact',c)}
const IMPACTS={
 payment:[['Cash Flow Impact','$4.5M delayed','Overdue receipts could move beyond Q4; the collection scenario targets $1.5M recovered.'],['Revenue Impact','No change booked','Payment delay alone does not reduce recognized revenue. $5.2M annual renewal value remains a separate review.'],['Margin Impact','Not quantified','Additional collection effort may raise cost; no incremental cost estimate is available.'],['Working Capital Impact','$4.5M tied up','The same overdue AR is capital tied up, not a second financial loss.'],['Credit Exposure','$4.5M open AR','Gross AR at risk, before collateral or recovery assumptions. $42M financed principal is shown separately, not added.'],['Portfolio Yield Impact','Not estimated','Yield sensitivity requires loss and funding assumptions beyond this event.']],
 modification:[['Cash Flow Impact','Timing unconfirmed','Receipts depend on the effective date and the accepted payment schedule.'],['Revenue Impact','−$300K / year','10% × $3M annual renewal value, if the full requested flex-down is accepted.'],['Margin Impact','−$51K / year','Illustrative: $300K less annual revenue × unchanged 17% margin. Service-cost adjustments may change this.'],['Working Capital Impact','$700K overdue','Existing overdue AR remains a separate collection issue; no incremental capital release is assumed.'],['Credit Exposure','$1.7M open AR','Existing gross AR. Do not add contract principal or annual renewal value to this balance.'],['Portfolio Yield Impact','Not estimated','A recalculation requires revised finance income and financed principal.']],
 renewal:[['Cash Flow Impact','Timing at risk','A one-quarter renewal delay could shift receipts; no payment schedule has been confirmed.'],['Revenue Impact','$4.2M under review','Annual renewal value, not an expected loss. One-quarter timing sensitivity is $1.05M if service stops during a full quarter.'],['Margin Impact','26% current margin','Future margin depends on agreed price and service scope. No change is booked.'],['Working Capital Impact','$300K overdue','Existing receivables remain outstanding during renewal discussions.'],['Credit Exposure','$1.2M open AR','Current gross receivable balance; independent of the future renewal value.'],['Portfolio Yield Impact','9.6% current yield','Account baseline, not a predicted change. Review revised terms before recalculating.']],
 credit:[['Cash Flow Impact','$4.5M under review','Same balance as the Payment Delay event. The credit outlook is not an additional cash shortfall.'],['Revenue Impact','No change booked','New commitments may be reviewed; no revenue reduction is assumed from an outlook change alone.'],['Margin Impact','Not quantified','Any impairment requires a separate supported assessment; none is modeled here.'],['Working Capital Impact','$4.5M tied up','Same overdue AR, shown as working capital rather than incremental exposure.'],['Credit Exposure','$4.5M open AR','Gross AR exposure, not estimated loss. Remaining contract value and collateral are not available for a net credit estimate.'],['Portfolio Yield Impact','Not estimated','No expected-loss modifier has been calibrated for the credit context.']],
 expansion:[['Cash Flow Impact','+$400K in Q4','Conditional scenario: receipts from a contracted November start; not committed cash.'],['Revenue Impact','+$600K in Q4','Assumes a portion of the $4M opportunity is contracted and delivered in Q4. Base forecast remains unchanged.'],['Margin Impact','+$174K in Q4','Illustrative $600K revenue × current 29% margin; assumes unchanged unit economics.'],['Working Capital Impact','+$200K requirement','Scenario revenue less cash receipts: $600K − $400K. Simplified AR bridge, excluding tax and billing timing.'],['Credit Exposure','$800K current AR','All current. Conditional incremental AR of $200K would require credit review; it is not booked.'],['Portfolio Yield Impact','10.2% current yield','Existing account baseline. Expansion yield is not estimated until financing terms are agreed.']],
 market:[['Cash Flow Impact','Not quantified','Service-cost cash effects require a validated cost and payment schedule.'],['Revenue Impact','$5.2M revenue base','No sector-wide decline is applied automatically. This is the annual revenue base for margin analysis.'],['Margin Impact','−$208K / year','(22% − 18%) × $5.2M annual revenue. This annualized sensitivity is not a newly booked expense.'],['Working Capital Impact','$4.5M overdue','Shared balance with Payment Delay. Do not count it again as sector-related exposure.'],['Credit Exposure','$4.5M open AR','Existing receivable exposure is unchanged by this margin analysis.'],['Portfolio Yield Impact','8.4% current yield','Operating margin and portfolio yield differ. No yield change is inferred directly from the 4-point margin gap.']]
};
function financialImpact(){const c=currentCase();return stepHead('Financial Impact Assessment','So what? Translate the assessment into financial consequences.','impact',c)+`<div class="impact-banner"><div><span class="eyebrow">IMPORTANCE RANK ${c.rank} · ${c.severity.toUpperCase()} PRIORITY</span><h2>${dollars(c.amount)}</h2><p>${c.amountLabel} · ${account(c).name}</p></div><div><h3>Potential business outcome</h3><p>${c.impact}</p><p>${c.benefit}</p></div></div><div class="impact-grid">${IMPACTS[c.id].map(([label,value,desc])=>`<article class="panel impact-tile"><span class="eyebrow">${label}</span><h2>${value}</h2><p>${desc}</p></article>`).join('')}</div><div class="grid equal">${panel('From consequence to action',`<div class="insight" style="margin-top:0"><strong>${c.reason}</strong><br>Therefore: ${c.rec.toLowerCase()}.</div><div class="stat-row"><span>Illustrative outcome target</span><strong>${dollars(c.target)}</strong></div><p>${c.metric}</p><p class="note">Target is a planning objective, not a promised benefit. The Decision Center records actual simulated results separately.</p>`)}${panel('Prioritization context',`<div class="priority-bars">${CASES.filter(x=>x.id!=='credit').sort((a,b)=>a.rank-b.rank).map(x=>`<a href="${go('impact',x)}"><span>${x.category}</span><span class="priority-bar"><i style="width:${(5-x.rank)*24}%"></i></span><strong>P${x.rank}</strong></a>`).join('')}</div><p class="note">Illustrative importance reflects urgency, exposure and ability to act. Different financial measures are not added together. Credit review shares the payment exposure and is excluded from this comparison.</p>`)}</div>`+nextStep('recommendations','Compare recommended actions',c)}
function recommendations(){const c=currentCase(),d=decision(c);const selected=ui.options?.[c.id]??d.option;return stepHead('Recommendations','Compare viable actions before making a Finance decision.','recommendations',c)+`<section class="panel recommendation-summary"><div><span class="eyebrow">RECOMMENDED ACTION</span><h2>${c.rec}</h2><p>${c.reason}</p></div>${badge(c.severity)}<div class="recommendation-meta"><span>Expected benefit<strong>${c.benefit}</strong></span><span>Owner<strong>${c.owner}</strong></span><span>Target completion<strong>${dateLabel(c.targetDate)}</strong></span></div></section><div class="options-grid">${c.options.map((o,i)=>`<article class="panel option-card ${i===0?'recommended':''} ${i===selected?'chosen':''}"><div class="action-meta"><span>OPTION ${'ABC'[i]}</span>${i===0?'<span class="pill blue">Recommended</span>':''}</div><h2>${o[0]}</h2><p>${o[1]}</p><dl><dt>Benefit</dt><dd>${o[2]}</dd><dt>Trade-off</dt><dd>${o[3]}</dd></dl><button data-select-option="${i}" ${['Approved','In Progress','Completed','Outcome Achieved'].includes(d.status)?'disabled':''}>${i===selected?'Selected for Finance review':'Choose this option'}</button></article>`).join('')}</div><div class="insight"><strong>Finance remains in control.</strong> The recommended option and Finance’s selected option are recorded separately. Approval records a decision; it does not execute a transaction.</div>`+nextStep('decisions','Review and decide',c)}
function historyMarkup(c,d){return `<ol class="decision-history"><li><span class="history-dot"></span><div><strong>Recommendation generated</strong><time>${dateLabel(c.detected)} · Recommendation v1</time><p>${c.rec}</p></div></li>${d.history.map(h=>`<li><span class="history-dot"></span><div><strong>${esc(h.status)}</strong><time>${new Date(h.at).toLocaleString('en-US',{timeZone:'America/New_York'})} ET · ${esc(h.owner)}</time><p>${esc(h.note)}</p>${h.option!==undefined?`<small>Finance option: ${esc(c.options[h.option]?.[0]||'Unknown')} · Target: ${dollars(h.target??c.target)}</small>`:''}</div></li>`).join('')}</ol>`}
function decisionDetail(c){const d=decision(c);const selected=ui.options?.[c.id]??d.option;const canDecide=d.status==='Recommended';return `<section class="panel" id="finance-review"><div class="panel-head"><div><h2>Finance review · ${account(c).name}</h2><p>${c.type} → ${c.rec}</p></div>${statusBadge(d.status)}</div><div class="decision-distinction"><div><span>Platform recommendation</span><strong>${c.options[0][0]}</strong></div><div><span>Finance decision</span><strong>${d.status==='Recommended'?'Awaiting review':c.options[d.option][0]}</strong></div><div><span>Nexbill execution</span><strong>${['In Progress','Completed','Outcome Achieved'].includes(d.status)?d.status==='In Progress'?'Simulated · in progress':'Simulated · completed':'Not started'}</strong></div></div>${canDecide?`<form id="finance-review-form"><div class="review-fields"><label class="form-field">Selected action<select name="option">${c.options.map((o,i)=>`<option value="${i}" ${i===selected?'selected':''}>${'ABC'[i]} · ${o[0]}</option>`).join('')}</select></label><label class="form-field">Decision owner<input name="owner" value="${esc(d.owner)}" maxlength="120" required></label><label class="form-field">Target completion date<input type="date" name="due" value="${esc(d.targetDate)}" min="2026-10-22" required></label><label class="form-field">Outcome target · USD millions<input name="target" type="number" min="0.001" max="${c.max}" step="0.001" value="${d.target??c.target}" required></label></div><p class="note">Outcome measure: ${c.metric}. Record a realistic target for the selected action; this is not an expected-loss calculation.</p><label class="form-field">Decision rationale<textarea name="note" rows="2" placeholder="Explain your approval, adjustment or rejection." maxlength="2000" required></textarea></label><div class="form-actions"><button name="decision" value="Rejected" type="submit">Reject recommendation</button><button name="decision" value="Approved" type="submit" class="primary">Approve selected action</button></div></form>`:`<div class="review-summary"><p><strong>Owner:</strong> ${esc(d.owner)} · <strong>Target completion:</strong> ${dateLabel(d.targetDate)}</p><p><strong>Outcome target:</strong> ${dollars(d.target??c.target)} · ${c.metric}</p><p>${esc(d.note||'')}</p></div><div class="status-action">${d.status==='Approved'?'<p>Finance approved the action. Nexbill execution has not started.</p><button class="primary" data-transition="In Progress">Simulate Nexbill execution start</button>':d.status==='In Progress'?'<p>The approved action is in progress in the simulated Nexbill workflow.</p><button class="primary" data-transition="Completed">Simulate execution completed</button>':d.status==='Rejected'?'<p>No action will proceed. Review the recommendation before reopening.</p><button data-transition="Recommended">Reopen Finance review</button>':(d.observed===undefined?'<p>Execution is complete. Measure the outcome separately from completion.</p>':'<p>Execution and outcome measurement are complete. Review the result below.</p>')}</div>`}${['Completed','Outcome Achieved'].includes(d.status)?`<div class="outcome-section"><h3>Outcome measurement</h3>${d.observed===undefined?`<form id="outcome-form"><div class="review-fields"><label class="form-field">${c.metric} · USD millions<input name="observed" type="number" min="0" max="${c.max}" step="0.001" required placeholder="Enter observed amount"></label><label class="form-field">Evidence / result summary<input name="evidence" maxlength="1000" required placeholder="e.g. Payment receipt confirmed in the demo"></label></div><button type="submit" class="primary">Record simulated outcome</button></form>`:`<div class="value-summary"><div><strong>${dollars(d.target)}</strong><span>Target</span></div><div><strong>${dollars(d.observed)}</strong><span>Observed · simulated</span></div><div><strong>${Math.round(d.observed/d.target*100)}%</strong><span>Target attainment</span></div></div><p>${esc(d.evidence)}</p><p class="note">${d.observed>=d.target?'Target achieved.':'Execution completed; outcome target not achieved.'} This result is not added to unrelated financial measures.</p>`}</div>`:''}<p class="note">Local prototype only. Approvals, execution states and outcomes do not change production Nexbill or accounting records.</p><details class="history-disclosure"><summary>Recommendation & decision history (${d.history.length+1} entries)</summary>${historyMarkup(c,d)}</details></section>`}
function decisionCenter(){const c=currentCase();const all=CASES.map(x=>({c:x,d:decision(x)}));const rows=all.filter(x=>ui.decisionFilter==='All statuses'||x.d.status===ui.decisionFilter);return stepHead('Business Decision Center','Review decisions, track execution and measure the outcome.','decisions',c)+`<div class="status-cards">${['Recommended','Approved','Rejected','In Progress','Completed','Outcome Achieved'].map(s=>`<button data-status-filter="${s}" class="${s===ui.decisionFilter?'selected':''}"><strong>${all.filter(x=>x.d.status===s).length}</strong><span>${s}</span></button>`).join('')}</div>`+decisionDetail(c)+panel('Decision register',`<div class="filter-row"><label for="decision-filter">Status</label><select id="decision-filter">${['All statuses','Recommended','Approved','Rejected','In Progress','Completed','Outcome Achieved'].map(s=>`<option ${s===ui.decisionFilter?'selected':''}>${s}</option>`).join('')}</select><span class="count">${rows.length} decisions</span></div><div class="table-wrap"><table><thead><tr><th>Event / customer</th><th>Owner</th><th>Target date</th><th>Status</th><th>Observed result</th><th>Review</th></tr></thead><tbody>${rows.map(({c:x,d})=>`<tr><td>${x.type}<small>${account(x).name}</small></td><td>${esc(d.owner)}</td><td>${dateLabel(d.targetDate)}</td><td>${statusBadge(d.status)}</td><td>${d.observed!==undefined?dollars(d.observed):'Not measured'}<small>${x.metric}</small></td><td><a href="${go('decisions',x)}">Open →</a></td></tr>`).join('')}</tbody></table>${!rows.length?'<p class="empty">No decisions in this status.</p>':''}</div>`,'One decision per event; shared exposure is not counted twice as realized value')}
function render(){const r=route(),c=currentCase();ui.event=c.id;document.getElementById('navigation').innerHTML=pages.map(([key,label,icon])=>`<a href="${key==='dashboard'?'#dashboard':go(key,c)}" class="${r.page===key?'active':''}" ${r.page===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join('');document.getElementById('crumb').textContent=pages.find(p=>p[0]===r.page)[1];document.getElementById('main').innerHTML=({dashboard:overview,events:businessEvents,signals,analysis,impact:financialImpact,recommendations,decisions:decisionCenter}[r.page])();document.title=pages.find(p=>p[0]===r.page)[1]+' | LeaseAegis'}
function showAnalysis(id){const c=CASES.find(x=>x.id===id);const dialog=document.getElementById('action-dialog');dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${c.category}</h2><button class="close" data-detail-close aria-label="Close analysis">×</button></div><p>${account(c).name} · ${c.title}</p><div class="decision-distinction"><div><span>${c.category==='Growth Opportunity'?'Opportunity':'Risk'} score</span><strong>${c.score} / 100</strong></div><div><span>Trend</span><strong>${c.trend}</strong></div><div><span>Confidence</span><strong>${c.confidence}</strong></div></div><h3>Driver explanation</h3><p>${c.driver}</p><h3>Evidence used</h3><ul>${c.internal.slice(0,3).map(x=>`<li>${x}</li>`).join('')}</ul><h3>Business summary</h3><p>${c.summary}</p><p class="note">Illustrative scores. External context supports interpretation; it is not a calibrated risk modifier.</p><a class="button primary" href="${go('impact',c)}" data-detail-close>Assess financial impact →</a>`;dialog.showModal()}
const BRIEFS={
 attention:['What requires immediate attention?','Global Telecom has $4.5M more than 90 days overdue. Three portfolio renewals are within 30 days.','Delayed receipts and unconfirmed renewal scope create cash and revenue uncertainty.','Start with collection follow-up, then review near-term renewals.','payment'],
 collection:['Which customers have rising collection risk?','Global Telecom has $4.5M overdue; Retail has $1.2M. Together they represent $5.7M of the $6.7M overdue portfolio.','Receipts may slip beyond the planning period. Overdue AR is not a confirmed loss.','Obtain dated payment commitments and review limits before new commitments.','payment'],
 margin:['What is driving profitability decline?','Global Telecom margin fell from 22% to 18%. Cost and price effects require investigation.','At $5.2M annual revenue, the four-point gap represents $208K annual profit sensitivity.','Review service, funding and collection costs alongside renewal pricing.','market'],
 renewal:['Which renewals may affect future revenue?','Retail, North America Data Center and European Network renew within 30 days.','Their combined annual renewal value is $10.8M. This is revenue under review, not an expected loss.','Confirm scope and dates, prioritizing payment issues and requested flex-downs.','renewal']
};
function openAdvisor(){const b=BRIEFS[ui.advisor];const d=document.getElementById('advisor-panel');d.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">OPTIONAL FINANCE BRIEF</span><h2 id="advisor-title">AI Advisor</h2></div><button class="close" data-advisor-close aria-label="Close Advisor">×</button></div><p>Briefings support your current workflow; Finance keeps the decision.</p><form id="brief-form" class="brief-form"><label for="brief-input">Ask about the portfolio</label><input id="brief-input" name="question" required maxlength="500" placeholder="What requires immediate attention?"><button type="submit" class="primary">Get briefing</button></form><div class="brief-prompts">${Object.entries(BRIEFS).map(([key,v])=>`<button data-brief="${key}">${v[0]}</button>`).join('')}</div><div aria-live="polite">${b?`<h3>${b[0]}</h3>${['Observation','Impact','Recommendation'].map((label,i)=>`<div class="brief-section"><h3>${label}</h3><p>${b[i+1]}</p></div>`).join('')}<a href="#recommendations/${b[4]}" data-advisor-close>Review the related recommendation →</a>`:'<h3>Observation</h3><p>This demo covers collection, renewal and profitability questions.</p><h3>Impact</h3><p>The available information does not support that question.</p><h3>Recommendation</h3><p>Select a suggested briefing or narrow the question to one of these topics.</p>'}</div><p class="note">Illustrative portfolio briefings, not a live AI service.</p>`;if(!d.open)d.showModal()}
let toastTimer;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5000)}
function transition(next){const c=currentCase(),d=decision(c);const allowed={Approved:'In Progress','In Progress':'Completed',Rejected:'Recommended'};if(allowed[d.status]!==next)return;const note=next==='In Progress'?'Simulated Nexbill execution started; no production request created.':next==='Completed'?'Simulated execution completed; financial outcome is not yet measured.':'Finance review reopened; previous decision remains in history.';d.status=next;d.history.push({status:next,at:new Date().toISOString(),owner:d.owner,note,option:d.option,target:d.target});if(persist(c,d)){render();toast(note)}}
document.addEventListener('click',e=>{const target=e.target.closest('button,a');if(!target)return;if(target.hasAttribute('data-analysis-detail'))showAnalysis(target.dataset.analysisDetail);if(target.hasAttribute('data-detail-close'))document.getElementById('action-dialog').close();if(target.hasAttribute('data-select-option')){ui.options??={};ui.options[currentCase().id]=Number(target.dataset.selectOption);render();toast('Option selected for Finance review. No decision has been approved.')}if(target.hasAttribute('data-status-filter')){ui.decisionFilter=target.dataset.statusFilter;render()}if(target.hasAttribute('data-transition'))transition(target.dataset.transition);if(target.hasAttribute('data-advisor-open'))openAdvisor();if(target.hasAttribute('data-advisor-close'))document.getElementById('advisor-panel').close();if(target.hasAttribute('data-brief')){ui.advisor=target.dataset.brief;openAdvisor()}});
document.addEventListener('change',e=>{if(e.target.id==='event-context')location.hash=route().page+'/'+e.target.value;if(e.target.id==='event-severity'){ui.eventFilter=e.target.value;render();document.getElementById('event-severity').focus()}if(e.target.id==='decision-filter'){ui.decisionFilter=e.target.value;render();document.getElementById('decision-filter').focus()}});
document.addEventListener('input',e=>{if(e.target.id==='event-search'){ui.search=e.target.value;render();document.getElementById('event-search').focus()}});
document.addEventListener('submit',e=>{if(e.target.id==='finance-review-form'){e.preventDefault();const c=currentCase(),d=decision(c);if(d.status!=='Recommended')return;const f=new FormData(e.target),owner=f.get('owner').trim(),note=f.get('note').trim(),due=f.get('due'),target=Number(f.get('target')),option=Number(f.get('option')),status=e.submitter?.value;if(!owner||!note||!['Approved','Rejected'].includes(status)||!Number.isInteger(option)||!c.options[option]||!due||due<'2026-10-22'||!Number.isFinite(target)||target<=0||target>c.max){toast('Enter a valid owner, rationale, target date and outcome target.');return}Object.assign(d,{owner,note,targetDate:due,target,option,status});d.history.push({status,at:new Date().toISOString(),owner,note,option,target});if(persist(c,d)){if(ui.options)delete ui.options[c.id];render();toast(status==='Approved'?'Finance decision approved. Nexbill execution has not started.':'Recommendation rejected. No action will proceed.')}}
 if(e.target.id==='outcome-form'){e.preventDefault();const c=currentCase(),d=decision(c);if(d.status!=='Completed'||d.observed!==undefined)return;const f=new FormData(e.target),raw=f.get('observed'),observed=Number(raw),evidence=f.get('evidence').trim();if(raw===''||!Number.isFinite(observed)||observed<0||observed>c.max||!evidence){toast('Enter a valid measured amount and supporting result summary.');return}d.observed=observed;d.evidence=evidence;d.status=observed>=d.target?'Outcome Achieved':'Completed';d.history.push({status:observed>=d.target?'Outcome Achieved':'Outcome measured · below target',at:new Date().toISOString(),owner:d.owner,note:`${c.metric}: ${dollars(observed)}. ${evidence}`,option:d.option,target:d.target});if(persist(c,d)){render();toast('Simulated outcome recorded separately from execution status.')}}
 if(e.target.id==='brief-form'){e.preventDefault();const q=new FormData(e.target).get('question').toLowerCase();ui.advisor=/renew|contract/.test(q)?'renewal':/profit|margin|cost/.test(q)?'margin':/collect|payment|cash/.test(q)?'collection':/attention|priorit|immediate|summary/.test(q)?'attention':'unknown';openAdvisor()}});
window.addEventListener('hashchange',()=>{for(const id of ['action-dialog','advisor-panel'])document.getElementById(id).close();render();window.scrollTo(0,0);document.getElementById('main').focus({preventScroll:true})});
render();
